{
  "flashcards": [
    {
      "front": "How do you design distributed systems to handle partial failure gracefully?",
      "back": "Implement circuit breakers, retries with exponential backoff, timeouts, and bulkhead patterns. Ensure services are idempotent and use asynchronous communication (queues) where possible to decouple dependencies and prevent cascading failures.",
      "requirement_ids": [
        "r2"
      ]
    },
    {
      "front": "What is the primary goal of multi-tenant isolation in Kubernetes?",
      "back": "To ensure that workloads from different tenants cannot access each other's data, interfere with performance, or compromise the cluster's security posture, typically achieved via Namespaces, NetworkPolicies, and RBAC.",
      "requirement_ids": [
        "r3",
        "r5"
      ]
    },
    {
      "front": "How do you effectively communicate complex technical architecture to non-technical stakeholders?",
      "back": "Focus on the 'why' rather than the 'how'. Use analogies, emphasize business value (cost, reliability, speed), and provide high-level diagrams that abstract away implementation details while highlighting key trade-offs.",
      "requirement_ids": [
        "r4"
      ]
    },
    {
      "front": "What are the trade-offs of using a service mesh in a large-scale Kubernetes environment?",
      "back": "Pros: Observability, mTLS, traffic management. Cons: Increased latency, operational complexity, and resource overhead. Use it only when the complexity of managing service-to-service communication manually exceeds the cost of the mesh.",
      "requirement_ids": [
        "r2",
        "r3"
      ]
    },
    {
      "front": "How do you ensure infrastructure reliability when managing 8+ years of legacy systems alongside new tech?",
      "back": "Prioritize observability and automated testing. Treat infrastructure as code (IaC) to ensure reproducibility. Implement gradual migration strategies (strangler pattern) rather than big-bang rewrites to minimize risk during transitions.",
      "requirement_ids": [
        "r1",
        "r2"
      ]
    },
    {
      "front": "What is the 'Bulkhead' pattern in distributed systems?",
      "back": "Isolating resources so that a failure in one component does not consume all system resources, preventing total system collapse. Examples include separate thread pools or dedicated clusters for different service tiers.",
      "requirement_ids": [
        "r2"
      ]
    },
    {
      "front": "How do you enforce resource isolation for multi-tenant Kubernetes clusters?",
      "back": "Use ResourceQuotas and LimitRanges to prevent a single tenant from consuming all cluster CPU/memory. Combine these with PodSecurityPolicies (or Pod Security Admission) and NetworkPolicies to restrict cross-namespace traffic.",
      "requirement_ids": [
        "r3",
        "r5"
      ]
    },
    {
      "front": "What makes a technical design document (TDD) effective for a Staff-level engineer?",
      "back": "It clearly defines the problem, evaluates multiple alternatives with pros/cons, provides a recommendation, and addresses security, scalability, and operational impact. It serves as a decision log for future engineers.",
      "requirement_ids": [
        "r4"
      ]
    },
    {
      "front": "How do you handle 'noisy neighbor' issues in multi-tenant environments?",
      "back": "Implement strict resource limits, use priority classes to schedule critical workloads, and leverage node affinity or taints/tolerations to physically separate high-demand tenants onto dedicated hardware nodes.",
      "requirement_ids": [
        "r3",
        "r5"
      ]
    },
    {
      "front": "Why is idempotency critical in distributed systems?",
      "back": "It ensures that performing the same operation multiple times yields the same result as performing it once. This is essential for safe retries in the face of network timeouts or partial failures.",
      "requirement_ids": [
        "r2"
      ]
    }
  ]
}
